// Good code: This snippet uses PreparedStatement to prevent SQL injection by parameterizing the query.
import java.sql.*;

public class SecureExample {
    public static void main(String[] args) throws Exception {
        String username = "admin' OR '1'='1"; // Simulated malicious user input
        String password = "anything";

        // Establish database connection
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");

        // Secure: Using PreparedStatement with placeholders to safely handle user input
        String sql = "SELECT * FROM users WHERE username = ? AND password = ?";
        PreparedStatement pstmt = conn.prepareStatement(sql);
        pstmt.setString(1, username);
        pstmt.setString(2, password);
        ResultSet rs = pstmt.executeQuery();

        if (rs.next()) {
            System.out.println("Login successful");
        } else {
            System.out.println("Login failed");
        }

        rs.close();
        pstmt.close();
        conn.close();
    }
}
